// Aggregate all data for content strategy agent
const signals = $('Fetch Top Signals (Last 7 Days)').all().map(i => i.json);
const trends = $('Fetch Trending Topics').all().map(i => i.json);
const approvedIdeas = $('Fetch Approved Content Ideas').all().map(i => i.json);

const weekStart = new Date();
weekStart.setDate(weekStart.getDate() + 1); // Tomorrow (Tuesday if run Monday)
const weekEnd = new Date(weekStart);
weekEnd.setDate(weekEnd.getDate() + 6);

return [{
  json: {
    week_start: weekStart.toISOString().split('T')[0],
    week_end: weekEnd.toISOString().split('T')[0],
    data: {
      signals,
      trends,
      approved_content_ideas: approvedIdeas,
      context: {
        total_signals: signals.length,
        total_trends: trends.length,
        ideas_in_queue: approvedIdeas.length,
        top_signal_categories: [...new Set(signals.map(s => s.signal_category))].slice(0, 5)
      }
    },
    generation_request: 'weekly_content_calendar',
    requested_at: new Date().toISOString()
  }
}];

// Parse content calendar from agent response
const response = $json;
const calendar = response.calendar || {};
const weeklyThemes = response.weekly_themes || [];
const contentPieces = response.content_pieces || [];

return [{
  json: {
    week_start: response.week_start || $('Aggregate Content Strategy Data').first().json.week_start,
    week_end: response.week_end || $('Aggregate Content Strategy Data').first().json.week_end,
    weekly_themes: weeklyThemes,
    content_pieces: contentPieces,
    total_pieces: contentPieces.length,
    calendar_summary: response.calendar_summary || '',
    generated_at: new Date().toISOString()
  }
}];

